    for r in range(1,H-1):
        for c in range(1,W-1):
            v=int(a[r,c])
            neigh=[int(a[rr,cc]) for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]]
            diag=[int(a[rr,cc]) for rr,cc in [(r-1,c-1),(r-1,c+1),(r+1,c-1),(r+1,c+1)]]
            if all(x==v for x in neigh) and any(d!=v for d in diag):
