def f(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(v for r in inp for v in r); bg=cnt.most_common(1)[0][0]
    # find plus centers: 4 orthogonal neighbors equal, != bg, != 3
    centers=[]
    for i in range(H):
        for j in range(W):
            if inp[i][j]==bg: continue
            nb=[inp[i-1][j],inp[i+1][j],inp[i][j-1],inp[i][j+1]]
            ok=all(0<=ii<H and 0<=jj<W and nb[k]!=bg and nb[k]==inp[i][j] for k,(ii,jj) in enumerate([( -1,0),(1,0),(0,-1),(0,1)]))
            # actually: all four in-bounds and equal to center
            if ok and inp[i][j]!=3:
                centers.append((i,j,inp[i][j]))
    out=[row[:] for row in inp]
    for ci,cj,c in sorted(centers):
        for ii in range(H):
            if out[ii][cj]==bg: out[ii][cj]=c
        for jj in range(W):
            if out[ci][jj]==bg: out[ci][jj]=c
    return out
